--
-- Create view `view_items`
--
CREATE
DEFINER = 'a8d6c0_pj3'@'%'
VIEW view_items
AS
SELECT
  `i`.`ItemId` AS `ItemId`,
  `i`.`ItemCode` AS `ItemCode`,
  `i`.`ItemName` AS `ItemName`,
  `i`.`Description` AS `Description`,
  `i`.`RealPrice` AS `RealPrice`,
  `i`.`SaleRate` AS `SaleRate`,
  `i`.`InStock` AS `InStock`,
  `i`.`Medias` AS `Medias`,
  `i`.`Tag` AS `Tag`,
  `i`.`CategoryCode` AS `CategoryCode`,
  `c`.`CategoryName` AS `CategoryName`,
  `i`.`CreatedAt` AS `CreatedAt`,
  `i`.`ModifiedAt` AS `ModifiedAt`
FROM (`item` `i`
  LEFT JOIN `category` `c`
    ON ((`i`.`CategoryCode` = `c`.`CategoryCode`)));

DELIMITER $$

--
-- Create procedure `Proc_GetItems`
--
CREATE DEFINER = 'a8d6c0_pj3'@'%'
PROCEDURE Proc_GetItems (IN CategoryCode varchar(40), IN SearchTerms varchar(255), IN Tag varchar(255), IN OrderState int, IN Indexx int, IN Count int, OUT Total int)
BEGIN
  SET @SearchTerms = SearchTerms;
  SET @CategoryCode = CategoryCode;
  SET @Tag = Tag;
  SET @OrderState = OrderState;
  DROP TEMPORARY TABLE IF EXISTS tmpTable;
  IF Count > 0 THEN
    CREATE TEMPORARY TABLE tmpTable AS (SELECT
        *
      FROM view_items i
      WHERE 1 = 1
      AND (
      (
      (
      i.ItemName LIKE CONCAT('%', @SearchTerms, '%')
      OR i.ItemCode LIKE CONCAT('%', @SearchTerms, '%')
      )
      AND @SearchTerms IS NOT NULL
      )
      OR @SearchTerms IS NULL
      )
      AND (
      (
      (
      i.CategoryCode LIKE CONCAT(@CategoryCode, '%')
      )
      AND @CategoryCode IS NOT NULL
      )
      OR @CategoryCode IS NULL
      )
      AND (
      (
      (
      i.Tag LIKE CONCAT('%', @Tag, '%')
      )
      AND @Tag IS NOT NULL
      )
      OR @Tag IS NULL
      ));

    SET Total = (SELECT
        COUNT(*)
      FROM tmpTable);

    IF @OrderState = 1 THEN
      SELECT
        *
      FROM tmpTable
      ORDER BY tmpTable.RealPrice DESC LIMIT Indexx, Count;
    ELSE
      SELECT
        *
      FROM tmpTable
      ORDER BY tmpTable.RealPrice ASC LIMIT Indexx, Count;
    END IF;
  END IF;
END
$$

