--
-- Create procedure `Proc_UseVoucher`
--
CREATE DEFINER = 'a8d6c0_pj3'@'%'
PROCEDURE Proc_UseVoucher (IN VoucherId char(36))
BEGIN
  UPDATE voucher v
  SET v.Quota = v.Quota - 1
  WHERE v.VoucherId = VoucherId
  AND v.Quota >= 0;
END
$$

