--
-- Create procedure `Proc_UpdateOrder`
--
CREATE DEFINER = 'a8d6c0_pj3'@'%'
PROCEDURE Proc_UpdateOrder (IN OrderId char(36), IN BuyerName varchar(255), IN Phone varchar(30), IN UnitCode varchar(20), IN Address text, IN Status int, IN PaymentMethod int, IN PaymentStatus boolean, IN Items text, IN TotalMoney double, IN Ship varchar(255), IN ShipPayStatus boolean, IN Email varchar(50), IN VoucherId char(36))
BEGIN
  UPDATE `order` o
  SET o.BuyerName = BuyerName,
      o.Phone = Phone,
      o.UnitCode = UnitCode,
      o.Address = Address,
      o.Status = Status,
      o.PaymentMethod = PaymentMethod,
      o.PaymentStatus = PaymentStatus,
      o.Items = Items,
      o.TotalMoney = TotalMoney,
      o.Ship = Ship,
      o.ShipPayStatus = ShipPayStatus,
      o.Email = Email,
      o.VoucherId = VoucherId,
      o.ModifiedAt = CURRENT_TIMESTAMP()
  WHERE o.OrderId = OrderId;
END
$$

