--
-- Create procedure `Proc_GetOrders`
--
CREATE DEFINER = 'a8d6c0_pj3'@'%'
PROCEDURE Proc_GetOrders (IN OrderStatus int, IN SearchTerms varchar(255), IN StartTime double, IN EndTime double, IN OrderTimeState int, IN Indexx int, IN Count int, OUT Total int)
COMMENT 'Lấy về danh sách order'
BEGIN
  SET @OrderStatus = OrderStatus;
  SET @SearchTerms = SearchTerms;
  SET @StartTime = StartTime;
  SET @EndTime = EndTime;
  SET @OrderTimeState = OrderTimeState;
  DROP TEMPORARY TABLE IF EXISTS tmpTable;
  IF Count > 0 THEN
    CREATE TEMPORARY TABLE tmpTable AS (SELECT
        *
      FROM `order` o
      WHERE 1 = 1
      AND (
      (
      (
      o.Status = @OrderStatus
      )
      AND @OrderStatus != 0
      )
      OR @OrderStatus = 0
      )
      AND (
      (
      (
      o.OrderCode LIKE CONCAT('%', @SearchTerms, '%')
      OR o.Phone LIKE CONCAT('%', @SearchTerms, '%')
      )
      AND @SearchTerms IS NOT NULL
      )
      OR @SearchTerms IS NULL
      )
      AND (
      UNIX_TIMESTAMP(o.CreatedAt) >= @StartTime
      AND UNIX_TIMESTAMP(o.CreatedAt) <= @EndTime
      ));

    SET Total = (SELECT
        COUNT(*)
      FROM tmpTable);

    IF @OrderTimeState = 1 THEN
      SELECT
        *
      FROM tmpTable
      ORDER BY tmpTable.CreatedAt DESC LIMIT Indexx, Count;
    ELSE
      SELECT
        *
      FROM tmpTable
      ORDER BY tmpTable.CreatedAt ASC LIMIT Indexx, Count;
    END IF;
  END IF;
END
$$

