--
-- Create procedure `Proc_UpdateAccount`
--
CREATE DEFINER = 'a8d6c0_pj3'@'%'
PROCEDURE Proc_UpdateAccount (IN AccountId char(36), IN AccountName varchar(100), IN Phone varchar(30), IN Email varchar(50), IN Password char(200), IN Role varchar(20))
COMMENT 'Cập nhật tài khoản'
BEGIN
  UPDATE account a
  SET a.AccountName = AccountName,
      a.Phone = Phone,
      a.Email = Email,
      a.Password = Password,
      a.Role = Role,
      a.ModifiedAt = CURRENT_TIMESTAMP()
  WHERE a.AccountId = AccountId;
END
$$

--
-- Create procedure `Proc_InsertAccount`
--
CREATE DEFINER = 'a8d6c0_pj3'@'%'
PROCEDURE Proc_InsertAccount (IN AccountName varchar(100), IN Phone varchar(30), IN Email varchar(50), IN Password char(200), IN Role varchar(20))
COMMENT 'Thêm mới 1 tài khoản'
BEGIN
  INSERT INTO account (AccountId, AccountName, Phone, Email, Password, Role, CreatedAt)
    VALUES (UUID(), AccountName, Phone, Email, Password, Role, CURRENT_TIMESTAMP());
END
$$

--
-- Create procedure `Proc_GetNewOrderCode`
--
CREATE DEFINER = 'a8d6c0_pj3'@'%'
PROCEDURE Proc_GetNewOrderCode ()
BEGIN
  SET @Random = FLOOR(RAND() * (9999 - 1111 + 1)) + 1111;
  SET @Time = UNIX_TIMESTAMP();
  SELECT
    CONCAT('DH', @Time, @Random) AS NewCode;
END
$$

